    @Test(expected = JsonMappingException.class)
    public void test_createContextual_badDefinition() throws JsonMappingException {
        JsonFormat.Value format = JsonFormat.Value.forShape(JsonFormat.Shape.STRING).withLocale(Locale.US).withTimeZone(TimeZone.getTimeZone("GMT"));
        DateFormat df = new DateFormat() {};
        when(serializers.getConfig().getDateFormat()).thenReturn(df);
        when(serializers.findFormatOverrides(any(), eq(property), eq(Date.class))).thenReturn(format);
        dateTimeSerializerBase.createContextual(serializers, property);
    }
}
