public class AnyGetterWriterTest{
private AnyGetterWriter anyGetterWriter;
    private SerializerProvider provider;
    private BeanProperty property;
    private AnnotatedMember accessor;
    private JsonSerializer<?> serializer;

    @Before
    public void setUp() throws Exception{
        ObjectMapper mapper = new ObjectMapper();
        provider = new StdSerializerProvider(mapper);
        property = new POJOProperty(new PropertyName("test"));
        accessor = new AnnotatedMember(new ObjectMapper(), new POJOClass()){};
        serializer = new JsonSerializer<Object>(){};
        anyGetterWriter = new AnyGetterWriter(property, accessor, serializer);
    }

    @Test
    public void testResolve_SerializerIsContextualSerializer() throws Exception{
        // Arrange
        JsonSerializer<?> contextualSerializer = mock(ContextualSerializer.class);
        anyGetterWriter = new AnyGetterWriter(property, accessor, contextualSerializer);

        // Act
        anyGetterWriter.resolve(provider);

        // Assert
        Assert.assertNotSame(contextualSerializer, anyGetterWriter._serializer);
    }

    @Test
    public void testResolve_SerializerIsNotContextualSerializer() throws Exception{
        // Arrange
        JsonSerializer<?> nonContextualSerializer = new JsonSerializer<Object>(){};
        anyGetterWriter = new AnyGetterWriter(property, accessor, nonContextualSerializer);

        // Act
        anyGetterWriter.resolve(provider);

        // Assert
        Assert.assertSame(nonContextualSerializer, anyGetterWriter._serializer);
    }

    @Test
    public void testResolve_SerializerIsMapSerializer() throws Exception{
        // Arrange
        MapSerializer mapSerializer = mock(MapSerializer.class);
        JsonSerializer<?> contextualMapSerializer = mock(ContextualSerializer.class);
        when(provider.handlePrimaryContextualization(any(JsonSerializer.class), any(BeanProperty.class))).thenReturn(contextualMapSerializer);
        when(contextualMapSerializer instanceof MapSerializer).thenReturn(true);
        when((MapSerializer) contextualMapSerializer).thenReturn(mapSerializer);
        anyGetterWriter = new AnyGetterWriter(property, accessor, mapSerializer);

        // Act
        anyGetterWriter.resolve(provider);

        // Assert
        Assert.assertNotNull(anyGetterWriter._mapSerializer);
    }

    @Test
    public void testResolve_SerializerIsNotMapSerializer() throws Exception{
        // Arrange
        JsonSerializer<?> contextualSerializer = mock(ContextualSerializer.class);
        when(provider.handlePrimaryContextualization(any(JsonSerializer.class), any(BeanProperty.class))).thenReturn(contextualSerializer);
        when(contextualSerializer instanceof MapSerializer).thenReturn(false);
        anyGetterWriter = new AnyGetterWriter(property, accessor, contextualSerializer);

        // Act
        anyGetterWriter.resolve(provider);

        // Assert
        Assert.assertNull(anyGetterWriter._mapSerializer);
    }
