public class NumberSerializerTest{
@Rule
    public ExpectedException thrown=ExpectedException.none();
    private NumberSerializer testObject;
    private ObjectMapper mapper = new ObjectMapper();

    @Before 
    public void before(){
        testObject = new NumberSerializer(Number.class);
    }

    @Test
    public void testAcceptJsonFormatVisitor_BigInteger() throws Exception {
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = JavaType.construct(BigInteger.class);
        testObject = new NumberSerializer(BigInteger.class);
        testObject.acceptJsonFormatVisitor(visitor, typeHint);
        verify(visitor).visitIntFormat(any(JsonFormatVisitorWrapper.class), eq(typeHint), eq(JsonParser.NumberType.BIG_INTEGER));
    }

    @Test
    public void testAcceptJsonFormatVisitor_BigDecimal() throws Exception {
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = JavaType.construct(BigDecimal.class);
        testObject.acceptJsonFormatVisitor(visitor, typeHint);
        verify(visitor).visitFloatFormat(any(JsonFormatVisitorWrapper.class), eq(typeHint), eq(JsonParser.NumberType.BIG_DECIMAL));
    }

    @Test
    public void testAcceptJsonFormatVisitor_Number() throws Exception {
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = JavaType.construct(Number.class);
        testObject.acceptJsonFormatVisitor(visitor, typeHint);
        verify(visitor).expectNumberFormat(eq(typeHint));
    }

    @Test
    public void testHandledType(){
        Assert.assertEquals(Number.class, testObject.handledType());
    }

    @Test
    public void testSerialize() throws Exception {
        Number value = BigDecimal.valueOf(10);
        JsonGenerator generator = mock(JsonGenerator.class);
        SerializerProvider provider = mock(SerializerProvider.class);
        testObject.serialize(value, generator, provider);
        verify(generator).writeNumber(value);
    }

    @Test
    public void testGetSchema() throws Exception {
        SerializerProvider provider = mock(SerializerProvider.class);
        Type typeHint = Number.class;
        JsonNode schema = testObject.getSchema(provider, typeHint);
        Assert.assertNotNull(schema);
    }

    @After
    public void tearDown(){}
} 
