import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.util.*;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.util.ClassUtil;

public class POJOPropertyBuilderTest{
private POJOPropertyBuilder builder;
    private MapperConfig<?> config;
    private AnnotationIntrospector ai;
    private boolean forSerialization;
    private PropertyName internalName;

    @Before
    public void init(){
        ObjectMapper mapper = new ObjectMapper();
        config = mapper.getConfig();
        ai = new JacksonAnnotationIntrospector();
        forSerialization = true;
        internalName = new PropertyName("internalName");
        builder = new POJOPropertyBuilder(config, ai, forSerialization, internalName);
    }

    @Test
    public void testRemoveNonVisible(){
        JsonProperty.Access acc = builder.removeNonVisible(true);
        assertThat(acc, equalTo(JsonProperty.Access.AUTO));
    }

    @Test
    public void testRemoveNonVisible_ReadOnly(){
        JsonProperty.Access acc = JsonProperty.Access.READ_ONLY;
        assertThat(builder.removeNonVisible(true), equalTo(acc));
        assertNull(builder._setters);
        assertNull(builder._ctorParameters);
    }

    @Test
    public void testRemoveNonVisible_Read_Write(){
        JsonProperty.Access acc = JsonProperty.Access.READ_WRITE;
        assertThat(builder.removeNonVisible(true), equalTo(acc));
        assertNotNull(builder._getters);
        assertNotNull(builder._setters);
        assertNotNull(builder._ctorParameters);
        assertNotNull(builder._fields);
    }

    @Test
    public void testRemoveNonVisible_Write_Only(){
        JsonProperty.Access acc = JsonProperty.Access.WRITE_ONLY;
        assertThat(builder.removeNonVisible(true), equalTo(acc));
        assertNull(builder._getters);
    }

    @Test
    public void testRemoveNonVisible_Auto(){
        JsonProperty.Access acc = JsonProperty.Access.AUTO;
        assertThat(builder.removeNonVisible(true), equalTo(acc));
        assertNotNull(builder._getters);
        assertNotNull(builder._setters);
        assertNotNull(builder._ctorParameters);
        assertNotNull(builder._fields);
    }

    @Test
    public void testRemoveNonVisible_InferMutators_False(){
        JsonProperty.Access acc = builder.removeNonVisible(false);
        assertThat(acc, equalTo(JsonProperty.Access.AUTO));
    }
}
