public class ObjectIdInfoTest{
private ObjectIdInfo objectIdInfo;
    private PropertyName propertyName;
    private Class<?> scope;
    private Class<? extends ObjectIdGenerator<?>> generator;
    private Class<? extends ObjectIdResolver> resolver;

    @Before
    public void init(){
        propertyName = new PropertyName("test");
        scope = Object.class;
        generator = ObjectIdGenerators.IntSequenceGenerator.class;
        resolver = SimpleObjectIdResolver.class;
    }

    @Test
    public void testWithAlwaysAsId(){
        objectIdInfo = new ObjectIdInfo(propertyName, scope, generator, resolver);
        ObjectIdInfo result = objectIdInfo.withAlwaysAsId(true);
        assertNotSame(objectIdInfo, result);
        assertEquals(true, result.getAlwaysAsId());

        result = objectIdInfo.withAlwaysAsId(false);
        assertSame(objectIdInfo, result);
        assertEquals(false, result.getAlwaysAsId());
    }

    @Test
    public void testConstructors(){
        objectIdInfo = new ObjectIdInfo(propertyName, scope, generator, resolver);
        assertNotNull(objectIdInfo);
        assertEquals(propertyName, objectIdInfo.getPropertyName());
        assertEquals(scope, objectIdInfo.getScope());
        assertEquals(generator, objectIdInfo.getGeneratorType());
        assertEquals(resolver, objectIdInfo.getResolverType());
        assertEquals(false, objectIdInfo.getAlwaysAsId());

        objectIdInfo = new ObjectIdInfo(propertyName, scope, generator);
        assertNotNull(objectIdInfo);
        assertEquals(propertyName, objectIdInfo.getPropertyName());
        assertEquals(scope, objectIdInfo.getScope());
        assertEquals(generator, objectIdInfo.getGeneratorType());
        assertEquals(SimpleObjectIdResolver.class, objectIdInfo.getResolverType());
        assertEquals(false, objectIdInfo.getAlwaysAsId());

        objectIdInfo = new ObjectIdInfo(propertyName, scope, generator, true);
        assertNotNull(objectIdInfo);
        assertEquals(propertyName, objectIdInfo.getPropertyName());
        assertEquals(scope, objectIdInfo.getScope());
        assertEquals(generator, objectIdInfo.getGeneratorType());
        assertEquals(SimpleObjectIdResolver.class, objectIdInfo.getResolverType());
        assertEquals(true, objectIdInfo.getAlwaysAsId());

        objectIdInfo = new ObjectIdInfo(propertyName, scope, generator, true, resolver);
        assertNotNull(objectIdInfo);
        assertEquals(propertyName, objectIdInfo.getPropertyName());
        assertEquals(scope, objectIdInfo.getScope());
        assertEquals(generator, objectIdInfo.getGeneratorType());
        assertEquals(resolver, objectIdInfo.getResolverType());
        assertEquals(true, objectIdInfo.getAlwaysAsId());
    }

    @Test
    public void testGetters(){
        objectIdInfo = new ObjectIdInfo(propertyName, scope, generator, resolver);
        assertEquals(propertyName, objectIdInfo.getPropertyName());
        assertEquals(scope, objectIdInfo.getScope());
        assertEquals(generator, objectIdInfo.getGeneratorType());
        assertEquals(resolver, objectIdInfo.getResolverType());
        assertEquals(false, objectIdInfo.getAlwaysAsId());
    }

